import Ajv from 'ajv';
import {describe, it, expect, jest} from '@jest/globals';
import {ToolRegistry} from './registry.js';
import type {ToolExecutor} from './registry.js';

describe('ToolRegistry', () => {
  it('rejects input missing a required property with a ToolResponse and never calls the executor', async () => {
    const registry = new ToolRegistry();
    const executor: ToolExecutor = jest.fn(async () => 'ok');

    registry.register(
      {
        name: 'unit-test-tool',
        description: 'Used for unit testing validation',
        inputSchema: {
          type: 'object',
          properties: {
            val: {type: 'string'},
          },
          required: ['val'],
        },
      },
      executor
    );

    const response = await registry.execute('unit-test-tool', {});

    expect({
      result: response.result,
      calls: (executor as jest.Mock).mock.calls.length,
    }).toEqual({
      result: expect.stringContaining('val'),
      calls: 0,
    });
  });

  it('rejects a wrong-typed property without leaking the offending value', async () => {
    const registry = new ToolRegistry();
    const executor: ToolExecutor = jest.fn(async () => 'ok');

    registry.register(
      {
        name: 'type-test',
        description: 'desc',
        inputSchema: {
          type: 'object',
          properties: {
            count: {type: 'number'},
          },
        },
      },
      executor
    );

    const secretValue = 'SECRET_VALUE_DO_NOT_LEAK';
    const response = await registry.execute('type-test', {count: secretValue});

    expect({
      mentionsField: response.result.includes('count'),
      mentionsType: response.result.includes('number'),
      leaksValue: response.result.includes(secretValue),
      calls: (executor as jest.Mock).mock.calls.length,
    }).toEqual({
      mentionsField: true,
      mentionsType: true,
      leaksValue: false,
      calls: 0,
    });
  });

  it('throws at registration time for an uncompilable schema', () => {
    const registry = new ToolRegistry();
    const executor: ToolExecutor = jest.fn(async () => 'ok');

    expect(() => {
      registry.register(
        {
          name: 'broken-tool',
          description: 'A broken tool',
          inputSchema: {
            type: 'invalid-type',
          },
        },
        executor
      );
    }).toThrow(/broken-tool/);
  });

  it('passes through unlisted extra properties to the executor unchanged', async () => {
    const registry = new ToolRegistry();
    const executor: ToolExecutor = jest.fn(async (input: Record<string, unknown>) => {
      return `ok: ${JSON.stringify(input)}`;
    });

    registry.register(
      {
        name: 'extra-props-tool',
        description: 'desc',
        inputSchema: {
          type: 'object',
          properties: {
            known: {type: 'string'},
          },
        },
      },
      executor
    );

    const input = {known: 'value', extra: 'property'};
    await registry.execute('extra-props-tool', input);

    expect({
      callCount: (executor as jest.Mock).mock.calls.length,
      passedInput: (executor as jest.Mock).mock.calls[0][0],
    }).toEqual({
      callCount: 1,
      passedInput: input,
    });
  });

  it('compiles a static tool schema only once across multiple execute calls', async () => {
    const registry = new ToolRegistry();
    const executor: ToolExecutor = jest.fn(async () => 'ok');
    const compileSpy = jest.spyOn((registry as unknown as {ajv: Ajv}).ajv, 'compile');

    registry.register(
      {
        name: 'once-tool',
        description: 'desc',
        inputSchema: {
          type: 'object',
          properties: {
            foo: {type: 'string'},
          },
        },
      },
      executor
    );

    // One compilation at registration
    const initialCalls = compileSpy.mock.calls.length;

    for (let i = 0; i < 10; i++) {
      await registry.execute('once-tool', {foo: 'bar'});
    }

    // Still only one compilation
    expect(compileSpy.mock.calls.length).toBe(initialCalls);
    compileSpy.mockRestore();
  });

  it('validates against the current schema for function-valued tools whose schema changes', async () => {
    const registry = new ToolRegistry();
    const executor: ToolExecutor = jest.fn(async () => 'ok');

    const schema = {
      type: 'object',
      properties: {foo: {type: 'string'}},
      required: ['foo'],
    };

    registry.register(() => ({name: 'dynamic-tool', description: 'desc', inputSchema: schema as Record<string, unknown>}), executor);

    expect({
      res1: (await registry.execute('dynamic-tool', {foo: 'bar'})).result,
      res2: (await registry.execute('dynamic-tool', {})).result,
    }).toEqual({
      res1: 'ok',
      res2: expect.stringContaining('missing required property: foo'),
    });
  });

  it('validates against the current schema for function-valued tools whose schema changes (round 2)', async () => {
    const registry = new ToolRegistry();
    const executor: ToolExecutor = jest.fn(async () => 'ok');
    let schema: unknown = {type: 'object', properties: {foo: {type: 'string'}}, required: ['foo']};

    registry.register(() => ({name: 'dynamic-tool', description: 'desc', inputSchema: schema as Record<string, unknown>}), executor);

    // Change schema object
    schema = {
      type: 'object',
      properties: {bar: {type: 'number'}},
      required: ['bar'],
    };

    expect({
      res3: (await registry.execute('dynamic-tool', {bar: 123})).result,
      res4: (await registry.execute('dynamic-tool', {foo: 'bar'})).result,
    }).toEqual({
      res3: 'ok',
      res4: expect.stringContaining('missing required property: bar'),
    });
  });

  it('caches compiled validators for function-valued tools by schema object reference', async () => {
    const registry = new ToolRegistry();
    const executor: ToolExecutor = jest.fn(async () => 'ok');
    const compileSpy = jest.spyOn((registry as unknown as {ajv: Ajv}).ajv, 'compile');

    const schema1 = {type: 'object', properties: {foo: {type: 'string'}}};
    const schema2 = {type: 'object', properties: {bar: {type: 'number'}}};

    registry.register(() => ({name: 'cached-dynamic', description: 'desc', inputSchema: schema1 as Record<string, unknown>}), executor);

    // First call, first schema: compiles
    await registry.execute('cached-dynamic', {foo: 'bar'});
    const callsAfterFirst = compileSpy.mock.calls.length;

    // Second call, same schema object: should NOT compile
    await registry.execute('cached-dynamic', {foo: 'baz'});
    expect(compileSpy.mock.calls.length).toBe(callsAfterFirst);

    // Third call, different schema object: should compile
    registry.register(() => ({name: 'cached-dynamic', description: 'desc', inputSchema: schema2 as Record<string, unknown>}), executor);
    await registry.execute('cached-dynamic', {bar: 123});
    expect(compileSpy.mock.calls.length).toBe(callsAfterFirst + 1);

    compileSpy.mockRestore();
  });

  it('throws Unknown tool for an unregistered name', async () => {
    const registry = new ToolRegistry();
    await expect(registry.execute('non-existent', {})).rejects.toThrow('Unknown tool: non-existent');
  });
});

