  let round = 0;
  const provider: AIProvider = {
    async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
      round += 1;
      if (round === 1) {
        yield {type: 'tool_use', toolCall: {id: 'call-1', name: 'get_weather_retry', input: {}}};
        yield {type: 'stop', stopReason: 'tool_use'};
        return;
      }

      if (round === 2) {
        const {messages} = params;
        const lastMessage = messages[messages.length - 1] as ToolResultMessage;
        const {content} = lastMessage;
        firstRoundToolResult = content[0]?.content ?? '';
        yield {
          type: 'tool_use',
          toolCall: {id: 'call-2', name: 'get_weather_retry', input: {location: 'Paris'}},
        };
        yield {type: 'stop', stopReason: 'tool_use'};
        return;
      }

      yield {type: 'text', text: '22C in Paris'};
      yield {type: 'stop', stopReason: 'end_turn'};
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };

